class Solution {
public:
    int maxPotholes(string road, int budget) {
        vector<int> runs;
        for (int i = 0; i < (int)road.size();) {
            if (road[i] != 'x') { ++i; continue; }
            int j = i;
            while (j < (int)road.size() && road[j] == 'x') ++j;
            runs.push_back(j - i);
            i = j;
        }
        sort(runs.rbegin(), runs.rend());
        int ans = 0;
        for (int len : runs) {
            if (budget <= 1) break;
            int take = min(len, budget - 1);
            ans += take;
            budget -= take + 1;
        }
        return ans;
    }
};
